import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../../../core/services/api.service';

@Component({
  selector: 'app-article-list',
  standalone: true,
  imports: [CommonModule, RouterModule, FormsModule],
  template: `
    <div class="page-header"><div class="container"><h1>Cẩm Nang Du Lịch</h1><p>Kinh nghiệm, mẹo hay và lịch trình từ những người đã đi</p></div></div>
    <section class="section">
      <div class="container">
        <div class="filters-bar">
          <div class="filter-search">
            <span class="material-icons">search</span>
            <input type="text" [(ngModel)]="search" (ngModelChange)="loadArticles()" placeholder="Tìm kiếm bài viết..." class="search-input">
          </div>
          <select class="form-control" [(ngModel)]="category" (change)="loadArticles()">
            <option value="">Tất cả</option>
            <option *ngFor="let c of categories" [value]="c.slug">{{ c.name }}</option>
          </select>
        </div>
        <div class="loading-spinner" *ngIf="loading"><div class="spinner"></div></div>
        <div class="grid grid-3" *ngIf="!loading">
          <a *ngFor="let a of articles" [routerLink]="['/articles', a.slug]" class="card article-card fade-in">
            <div class="card-image">
              <img [src]="a.imageUrl || 'https://picsum.photos/seed/' + a.slug + '/400/250'" [alt]="a.title">
              <span class="badge badge-primary card-cat">{{ a.category?.name }}</span>
            </div>
            <div class="card-body">
              <h3>{{ a.title }}</h3>
              <p class="excerpt">{{ a.excerpt }}</p>
              <div class="card-meta">
                <span><span class="material-icons">visibility</span> {{ a.viewCount }}</span>
                <span><span class="material-icons">calendar_today</span> {{ a.publishedAt | date:'dd/MM/yyyy' }}</span>
              </div>
            </div>
          </a>
        </div>
        <div class="pagination" *ngIf="!loading && pagination.totalPages > 1">
          <button *ngFor="let p of pageNumbers" [class.active]="p === pagination.page" (click)="goToPage(p)">{{ p }}</button>
        </div>
      </div>
    </section>
  `,
  styles: [`
    .article-card { text-decoration: none; color: inherit; display: block; }
    .card-image { position: relative; height: 200px; overflow: hidden; img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.4s; } }
    .article-card:hover .card-image img { transform: scale(1.05); }
    .card-cat { position: absolute; bottom: 12px; left: 12px; }
    h3 { font-size: 1rem; margin-bottom: 0.5rem; }
    .excerpt { color: var(--gray); font-size: 0.875rem; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; margin-bottom: 0.75rem; }
    .card-meta { display: flex; gap: 1rem; color: var(--gray); font-size: 0.8125rem; span { display: flex; align-items: center; gap: 0.25rem; .material-icons { font-size: 1rem; } } }
    .filters-bar { display: flex; gap: 1rem; margin-bottom: 2rem; flex-wrap: wrap; align-items: center; }
    .filter-search { flex: 1; min-width: 250px; position: relative; .material-icons { position: absolute; left: 1rem; top: 50%; transform: translateY(-50%); color: var(--gray); } .search-input { padding-left: 2.75rem; } }
  `]
})
export class ArticleListComponent implements OnInit {
  articles: any[] = [];
  categories: any[] = [];
  loading = true;
  search = '';
  category = '';
  pagination: any = { page: 1, limit: 9, total: 0, totalPages: 0 };
  pageNumbers: number[] = [];
  constructor(private api: ApiService) {}
  ngOnInit() { this.loadCategories(); this.loadArticles(); }
  loadCategories() { this.api.getArticleCategories().subscribe(data => { this.categories = data; }); }
  loadArticles() {
    this.loading = true;
    const params: any = { page: this.pagination.page, limit: 9, category: this.category };
    if (this.search) params.search = this.search;
    this.api.getArticles(params).subscribe(res => {
      this.articles = res.data;
      this.pagination = res.pagination;
      this.pageNumbers = Array.from({length: Math.min(5, res.pagination.totalPages)}, (_, i) => i + 1);
      this.loading = false;
    }, () => { this.loading = false; });
  }
  goToPage(p: number) { this.pagination.page = p; this.loadArticles(); }
}
